#include <bits/stdc++.h>
using namespace std;

const int B = 20;
int n;
vector<array<int, B>> cnt;  // number of 1s per bit in each node
vector<long long> sum_;
vector<int> lazy_;

void build(int node, int l, int r, const vector<int> &a) {
    if (l == r) {
        for (int b = 0; b < B; b++) cnt[node][b] = (a[l] >> b) & 1;
        sum_[node] = a[l];
        return;
    }
    int m = (l + r) / 2;
    build(node * 2, l, m, a);
    build(node * 2 + 1, m + 1, r, a);
    for (int b = 0; b < B; b++) cnt[node][b] = cnt[node * 2][b] + cnt[node * 2 + 1][b];
    sum_[node] = sum_[node * 2] + sum_[node * 2 + 1];
}

void apply(int node, int len, int mask) {
    for (int b = 0; b < B; b++)
        if ((mask >> b) & 1) {
            int ones = cnt[node][b];
            cnt[node][b] = len - ones;
            sum_[node] += (long long)(len - 2 * ones) << b;
        }
    lazy_[node] ^= mask;
}

void push(int node, int l, int r) {
    if (lazy_[node]) {
        int m = (l + r) / 2;
        apply(node * 2, m - l + 1, lazy_[node]);
        apply(node * 2 + 1, r - m, lazy_[node]);
        lazy_[node] = 0;
    }
}

void update(int node, int l, int r, int ql, int qr, int mask) {
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) {
        apply(node, r - l + 1, mask);
        return;
    }
    push(node, l, r);
    int m = (l + r) / 2;
    update(node * 2, l, m, ql, qr, mask);
    update(node * 2 + 1, m + 1, r, ql, qr, mask);
    for (int b = 0; b < B; b++) cnt[node][b] = cnt[node * 2][b] + cnt[node * 2 + 1][b];
    sum_[node] = sum_[node * 2] + sum_[node * 2 + 1];
}

long long query(int node, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return 0;
    if (ql <= l && r <= qr) return sum_[node];
    push(node, l, r);
    int m = (l + r) / 2;
    return query(node * 2, l, m, ql, qr) + query(node * 2 + 1, m + 1, r, ql, qr);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    cnt.assign(4 * n, {});
    sum_.assign(4 * n, 0);
    lazy_.assign(4 * n, 0);
    build(1, 0, n - 1, a);
    int q;
    cin >> q;
    string out;
    while (q--) {
        int typ, s, e;
        cin >> typ >> s >> e;
        if (typ == 1) {
            out += to_string(query(1, 0, n - 1, s - 1, e - 1));
            out += '\n';
        } else {
            int z;
            cin >> z;
            update(1, 0, n - 1, s - 1, e - 1, z);
        }
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    static final int B = 20;
    static int[] cnt; // cnt[node * B + b]: number of 1s at bit b in the node
    static long[] sum;
    static int[] lazy;

    static void pull(int node) {
        for (int b = 0; b < B; b++) cnt[node * B + b] = cnt[2 * node * B + b] + cnt[(2 * node + 1) * B + b];
        sum[node] = sum[2 * node] + sum[2 * node + 1];
    }

    static void build(int node, int l, int r, int[] a) {
        if (l == r) {
            for (int b = 0; b < B; b++) cnt[node * B + b] = (a[l] >> b) & 1;
            sum[node] = a[l];
            return;
        }
        int m = (l + r) / 2;
        build(2 * node, l, m, a);
        build(2 * node + 1, m + 1, r, a);
        pull(node);
    }

    static void apply(int node, int length, int mask) {
        for (int b = 0; b < B; b++)
            if (((mask >> b) & 1) == 1) {
                int ones = cnt[node * B + b];
                cnt[node * B + b] = length - ones;
                sum[node] += (long) (length - 2 * ones) << b;
            }
        lazy[node] ^= mask;
    }

    static void push(int node, int l, int r) {
        if (lazy[node] != 0) {
            int m = (l + r) / 2;
            apply(2 * node, m - l + 1, lazy[node]);
            apply(2 * node + 1, r - m, lazy[node]);
            lazy[node] = 0;
        }
    }

    static void update(int node, int l, int r, int ql, int qr, int mask) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) {
            apply(node, r - l + 1, mask);
            return;
        }
        push(node, l, r);
        int m = (l + r) / 2;
        update(2 * node, l, m, ql, qr, mask);
        update(2 * node + 1, m + 1, r, ql, qr, mask);
        pull(node);
    }

    static long query(int node, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return sum[node];
        push(node, l, r);
        int m = (l + r) / 2;
        return query(2 * node, l, m, ql, qr) + query(2 * node + 1, m + 1, r, ql, qr);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        cnt = new int[4 * n * B];
        sum = new long[4 * n];
        lazy = new int[4 * n];
        build(1, 0, n - 1, a);
        StringBuilder out = new StringBuilder();
        for (int q = nextInt(); q > 0; q--) {
            int typ = nextInt(), s = nextInt() - 1, e = nextInt() - 1;
            if (typ == 1) out.append(query(1, 0, n - 1, s, e)).append('\n');
            else update(1, 0, n - 1, s, e, nextInt());
        }
        System.out.print(out);
    }
}

