import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

const B = 20

var cnt [][B]int32 // number of 1s per bit in each node
var sum []int64
var lazy []int32

func build(node, l, r int, a []int64) {
	if l == r {
		for b := 0; b < B; b++ {
			cnt[node][b] = int32(a[l] >> b & 1)
		}
		sum[node] = a[l]
		return
	}
	m := (l + r) / 2
	build(node*2, l, m, a)
	build(node*2+1, m+1, r, a)
	pull(node)
}

func pull(node int) {
	for b := 0; b < B; b++ {
		cnt[node][b] = cnt[node*2][b] + cnt[node*2+1][b]
	}
	sum[node] = sum[node*2] + sum[node*2+1]
}

func apply(node, length int, mask int32) {
	for b := 0; b < B; b++ {
		if mask>>b&1 == 1 {
			ones := cnt[node][b]
			cnt[node][b] = int32(length) - ones
			sum[node] += int64(int32(length)-2*ones) << b
		}
	}
	lazy[node] ^= mask
}

func push(node, l, r int) {
	if lazy[node] != 0 {
		m := (l + r) / 2
		apply(node*2, m-l+1, lazy[node])
		apply(node*2+1, r-m, lazy[node])
		lazy[node] = 0
	}
}

func update(node, l, r, ql, qr int, mask int32) {
	if qr < l || r < ql {
		return
	}
	if ql <= l && r <= qr {
		apply(node, r-l+1, mask)
		return
	}
	push(node, l, r)
	m := (l + r) / 2
	update(node*2, l, m, ql, qr, mask)
	update(node*2+1, m+1, r, ql, qr, mask)
	pull(node)
}

func query(node, l, r, ql, qr int) int64 {
	if qr < l || r < ql {
		return 0
	}
	if ql <= l && r <= qr {
		return sum[node]
	}
	push(node, l, r)
	m := (l + r) / 2
	return query(node*2, l, m, ql, qr) + query(node*2+1, m+1, r, ql, qr)
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	cnt = make([][B]int32, 4*n)
	sum = make([]int64, 4*n)
	lazy = make([]int32, 4*n)
	build(1, 0, n-1, a)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for q := nextInt(); q > 0; q-- {
		typ, s, e := nextInt(), int(nextInt())-1, int(nextInt())-1
		if typ == 1 {
			w.WriteString(strconv.FormatInt(query(1, 0, n-1, s, e), 10))
			w.WriteByte('\n')
		} else {
			update(1, 0, n-1, s, e, int32(nextInt()))
		}
	}
}
